window.__TEMA16_HTML="<style>\n.t16-visual-atlas,.t16-exam-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start;margin:12px 0 24px}\n.t16-visual-atlas .modality-study,.t16-exam-grid .realcase-card{min-width:0;width:100%;margin:0}\n.t16-visual-atlas .modality-study svg{max-height:205px;width:100%;display:block}\n.t16-exam-grid .realcase-card img{height:auto;width:100%;max-height:320px;object-fit:contain;background:#17232a}\n.t16-exam-grid .realcase-card h4{font-size:14px;line-height:1.4}\n.t16-direct{font-size:12px;font-weight:700;background:#e7f6f4;padding:10px 12px;border-radius:8px}\n.t16-direct a{color:#08727b;text-decoration:underline}\n.view .illustration{max-width:740px;margin-left:auto;margin-right:auto}\n@media(max-width:700px){.t16-visual-atlas,.t16-exam-grid{grid-template-columns:1fr}.t16-visual-atlas .modality-study svg{max-height:260px}}\n</style><div class=\"note\"><b>FICHA 16 · TRAUMA PANCREÁTICO E DUODENAL · UNIFESP 2027</b><br>ESQUEMA 1 / PADRÃO FICHA 7 · Resultado histórico: <b>12/12 (100%)</b>. Ficha teórica ANTES de dois casos clínicos expansíveis, com anatomia, fisiopatologia, exames reais, técnica cirúrgica, fluxogramas, complicações e discussão integrada após cada caso.</div><h2 class=\"section-band\">01 · ANATOMIA CIRÚRGICA DESENHADA</h2><div class=\"illustration\"><svg viewBox=\"0 0 800 360\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Desenho didático do pâncreas, ducto pancreático e quatro segmentos duodenais\"><rect width=\"800\" height=\"360\" rx=\"15\" fill=\"#eef6f7\"/><path d=\"M180 75 Q80 60 79 158 Q76 254 173 260 L250 260 Q275 252 272 218\" fill=\"none\" stroke=\"#dba889\" stroke-width=\"49\" stroke-linecap=\"round\"/><path d=\"M180 79 L180 108\" stroke=\"#dba889\" stroke-width=\"46\" stroke-linecap=\"round\"/><path d=\"M154 142 C192 118 230 120 263 142 C330 163 391 128 454 126 C510 124 570 135 650 115 L677 134 C606 162 536 169 473 157 C410 147 335 186 266 173 C221 171 180 176 154 142Z\" fill=\"#edc16e\" stroke=\"#bc9450\" stroke-width=\"4\"/><path d=\"M646 129 Q568 146 493 143 Q375 160 261 157 L175 157\" fill=\"none\" stroke=\"#426e80\" stroke-width=\"7\" stroke-linecap=\"round\"/><path d=\"M214 54 L214 179\" stroke=\"#b14c52\" stroke-width=\"10\"/><path d=\"M236 54 L236 183\" stroke=\"#4972ab\" stroke-width=\"10\"/><path d=\"M115 40 L130 124 L168 151\" fill=\"none\" stroke=\"#469164\" stroke-width=\"9\" stroke-linecap=\"round\"/><g fill=\"#29485a\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"600\"><text x=\"36\" y=\"39\">Colédoco</text><text x=\"88\" y=\"315\">D2</text><text x=\"245\" y=\"315\">D3</text><text x=\"95\" y=\"100\">D1</text><text x=\"306\" y=\"92\">Vasos mesentéricos</text><text x=\"530\" y=\"96\">Cauda</text><text x=\"350\" y=\"228\">Ducto de Wirsung</text><text x=\"330\" y=\"277\">Corpo pancreático</text><text x=\"30\" y=\"287\">D4</text></g><g stroke=\"#69828b\" stroke-width=\"2\"><path d=\"M96 43 L130 84\"/><path d=\"M382 102 L229 72\"/><path d=\"M417 207 L458 154\"/><path d=\"M382 258 L385 163\"/></g><text x=\"400\" y=\"340\" fill=\"#59717d\" font-size=\"15\" text-anchor=\"middle\">Esquema original simplificado: não está em escala, D3 cruza posteriormente aos vasos mesentéricos</text></svg><figcaption>Duodeno em C ao redor da cabeça pancreática; D2 relaciona-se com a ampola e o colédoco. Corpo/cauda pancreáticos estendem-se à esquerda dos vasos mesentéricos.</figcaption></div><div class=\"table-scroll\"><table><thead><tr><th>Estrutura</th><th>Importância em trauma</th></tr></thead><tbody><tr><td>Cabeça pancreática</td><td>Adjacente a D2, ampola, colédoco e grandes vasos; reconstrução complexa se destrutiva</td></tr><tr><td>Corpo/cauda</td><td>Ruptura ductal distal pode levar à pancreatectomia distal</td></tr><tr><td>Ducto de Wirsung</td><td>Integridade ductal é determinante central de fístula e escolha terapêutica</td></tr><tr><td>D1–D4</td><td>D2 contém a papila; D3 cruza anterior à aorta e posterior à artéria/veia mesentéricas superiores; lesões podem ser retroperitoneais</td></tr><tr><td>Retroperitônio</td><td>Lesões duodenais/pancreáticas podem ter poucos sinais peritoneais inicialmente</td></tr></tbody></table></div><div class=\"note\">MACETE: D2 = papila e bile. D3 = compressão contra coluna. Corpo/cauda + ducto rompido = pensar em ressecção distal em adulto.</div><h2 class=\"section-band\">01A · ATLAS VISUAL COMENTADO — CINCO DESENHOS DE REFERÊNCIA</h2><p class=\"explainer\">Complemento baseado nos cinco materiais anatômicos enviados para estudo: relações biliares e pancreáticas, D1–D4, operações duodenais, pancreatectomia total e peça anatômica. Os diagramas abaixo são reconstruções esquemáticas próprias, acompanhadas da interpretação de prova.</p><div class=\"t16-visual-atlas\"><details class=\"modality-study\" open><summary><b>ILUSTRAÇÃO 1 · AMPOLA DE VATER, PAPILAS, WIRSUNG E COLÉDOCO</b><span>Anatomia e interpretação</span></summary><div class=\"modality-inner\"><svg viewBox=\"0 0 650 245\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Colédoco e Wirsung formando ampola de Vater e abrindo em D2\"><rect width=\"650\" height=\"245\" rx=\"12\" fill=\"#f0f7f7\"/><path d=\"M115 30 C60 33 60 211 123 212 Q188 211 180 170\" fill=\"none\" stroke=\"#d6a28f\" stroke-width=\"48\"/><path d=\"M135 70 C180 55 224 86 286 74 C363 66 428 94 540 67\" fill=\"none\" stroke=\"#e5be6b\" stroke-width=\"41\" stroke-linecap=\"round\"/><path d=\"M524 68 L390 84 L263 80 L176 100 L127 133\" fill=\"none\" stroke=\"#2e7d98\" stroke-width=\"7\" stroke-linecap=\"round\"/><path d=\"M112 17 L121 80 L127 133\" stroke=\"#4c9859\" stroke-width=\"9\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"127\" cy=\"133\" r=\"10\" fill=\"#f2a854\" stroke=\"#8a4d3b\" stroke-width=\"3\"/><g fill=\"#204451\" font-family=\"sans-serif\" font-weight=\"600\" font-size=\"17\"><text x=\"12\" y=\"19\">Colédoco</text><text x=\"210\" y=\"33\">Wirsung</text><text x=\"365\" y=\"165\">Papila maior / ampola de Vater</text><text x=\"45\" y=\"237\">D2 duodenal</text><text x=\"375\" y=\"202\">Esfíncter de Oddi</text></g><path d=\"M280 38 L285 78 M390 150 L140 134 M406 190 L136 143\" stroke=\"#6c8891\" stroke-width=\"2\"/></svg><div class=\"explainer\"><p>Na primeira imagem fornecida, o <b>ducto hepático comum</b> se une ao <b>cístico</b> para formar o <b>colédoco</b>. O colédoco e o <b>Wirsung</b> geralmente convergem na <b>ampola hepatopancreática (Vater)</b>, que se abre na <b>papila duodenal maior</b>, em D2. O <b>esfíncter de Oddi</b> regula o fluxo de bile e secreção pancreática; as <b>válvulas de Heister</b> são pregas no ducto cístico. <b>Impacto cirúrgico:</b> lesão próxima à ampola exige avaliação de vias biliares e ducto pancreático, não apenas duodenorrafia.</p></div></div></details><details class=\"modality-study\" open><summary><b>ILUSTRAÇÃO 2 · D1–D4 E RECONSTRUÇÕES CIRÚRGICAS</b><span>Anatomia e interpretação</span></summary><div class=\"modality-inner\"><svg viewBox=\"0 0 650 250\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"650\" height=\"250\" rx=\"12\" fill=\"#f2f7f8\"/><g stroke=\"#bc846f\" stroke-width=\"29\" fill=\"none\" stroke-linecap=\"round\"><path d=\"M70 55 Q40 60 46 103 Q50 146 87 156 L150 156\"/><path d=\"M255 55 Q221 66 230 108 Q239 153 265 163 L319 163\"/><path d=\"M430 65 Q400 100 430 150 Q470 185 510 155 L555 130\"/></g><g stroke=\"#b45d5b\" stroke-width=\"5\" stroke-dasharray=\"7 5\"><path d=\"M95 143 L108 168\"/><path d=\"M260 148 L272 180\"/><path d=\"M483 157 L495 178\"/></g><g fill=\"#264d59\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"600\"><text x=\"34\" y=\"26\">Reparo primário</text><text x=\"232\" y=\"26\">Ressecção segmentar</text><text x=\"438\" y=\"26\">Reconstrução complexa</text><text x=\"35\" y=\"210\">Defeito pequeno, viável</text><text x=\"229\" y=\"210\">Lesão extensa, sem papila</text><text x=\"434\" y=\"210\">D2/ampola/cabeça</text></g></svg><div class=\"explainer\"><p>A segunda imagem mostra <b>localizações de tumores estromais duodenais (GIST)</b> e quatro opções de reconstrução: (i) gastrectomia distal com reconstrução em alça ou Y de Roux; (ii) ressecção em cunha e fechamento primário, ou duodenojejunostomia; (iii) duodenectomia segmentar com anastomose duodenojejunal; (iv) pancreaticoduodenectomia com pancreatojejunostomia ou pancreatogastrostomia. <b>Importante:</b> o estudo original é de <b>tumores</b>, não de trauma. As figuras ilustram anatomia e técnicas, mas <b>não são um algoritmo de indicação em trauma</b>. No trauma, sempre que seguro, prefere-se reparo primário em vez de ressecções complexas. <a target=\"_blank\" rel=\"noopener\" href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC5199143/\">Abrir a ilustração original do artigo</a>.</p></div></div></details><details class=\"modality-study\" open><summary><b>ILUSTRAÇÃO 3 · ANATOMIA DAS QUATRO PORÇÕES DO DUODENO</b><span>Anatomia e interpretação</span></summary><div class=\"modality-inner\"><svg viewBox=\"0 0 650 255\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"650\" height=\"255\" rx=\"12\" fill=\"#f3f8f9\"/><path d=\"M150 48 C70 48 70 198 170 208 L365 208 C415 208 432 153 498 141\" fill=\"none\" stroke=\"#cb927e\" stroke-width=\"50\" stroke-linecap=\"round\"/><g fill=\"#234959\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"700\"><text x=\"105\" y=\"30\">D1</text><text x=\"33\" y=\"136\">D2</text><text x=\"239\" y=\"247\">D3</text><text x=\"450\" y=\"118\">D4</text><text x=\"478\" y=\"200\">Jejuno</text></g><circle cx=\"121\" cy=\"145\" r=\"10\" fill=\"#eac362\" stroke=\"#91603e\" stroke-width=\"2\"/><text x=\"177\" y=\"135\" fill=\"#2a535c\" font-family=\"sans-serif\" font-size=\"15\">Papila em D2</text><path d=\"M174 132 L134 144\" stroke=\"#71909a\" stroke-width=\"2\"/></svg><div class=\"explainer\"><p>A terceira imagem ajuda a localizar: <b>D1</b> parte superior, do piloro até flexura superior; <b>D2</b> descendente, com papilas; <b>D3</b> horizontal, cruza atrás dos vasos mesentéricos superiores; <b>D4</b> ascendente até a <b>flexura duodenojejunal/ligamento de Treitz</b>. O duodeno é predominantemente retroperitoneal, exceto sua porção proximal e a transição; por isso, uma ruptura de D2–D4 pode produzir ar <b>retroperitoneal</b> sem pneumoperitônio volumoso.</p></div></div></details><details class=\"modality-study\" open><summary><b>ILUSTRAÇÃO 4 · PANCREATECTOMIA TOTAL × WHIPPLE</b><span>Anatomia e interpretação</span></summary><div class=\"modality-inner\"><svg viewBox=\"0 0 650 255\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"650\" height=\"255\" rx=\"12\" fill=\"#f4f8f8\"/><path d=\"M80 40 C45 42 43 111 75 120 L130 130\" stroke=\"#d5a190\" stroke-width=\"35\" fill=\"none\"/><path d=\"M205 42 L205 103\" stroke=\"#56a16f\" stroke-width=\"10\"/><path d=\"M245 134 C289 90 350 101 384 139 C431 195 474 179 510 142\" stroke=\"#c58872\" stroke-width=\"30\" fill=\"none\"/><path d=\"M205 101 L276 127\" stroke=\"#58a16e\" stroke-width=\"8\" stroke-dasharray=\"5 3\"/><path d=\"M95 120 L254 143\" stroke=\"#bf8471\" stroke-width=\"8\" stroke-dasharray=\"6 3\"/><path d=\"M323 100 L315 137\" stroke=\"#e7ba6c\" stroke-width=\"11\"/><g font-family=\"sans-serif\" font-weight=\"600\" font-size=\"16\" fill=\"#2a4d59\"><text x=\"27\" y=\"19\">Estômago</text><text x=\"142\" y=\"35\">Bile</text><text x=\"368\" y=\"85\">Pâncreas remanescente</text><text x=\"388\" y=\"228\">Jejuno</text><text x=\"28\" y=\"226\">Junções: alimento + bile + enzimas</text></g><path d=\"M391 91 L334 117\" stroke=\"#79909a\" stroke-width=\"2\"/></svg><div class=\"explainer\"><p>A quarta imagem fornecida está intitulada <b>pancreatectomia total</b>. Nessa operação, remove-se <b>todo o pâncreas</b>; se não sobra tecido pancreático, não existe anastomose pancreática. Isso é diferente da <b>pancreaticoduodenectomia clássica (Whipple)</b>, que retira a cabeça pancreática, duodeno e estruturas associadas, mas geralmente <b>preserva corpo/cauda</b>, exigindo anastomose do remanescente pancreático, anastomose biliar e reconstrução digestiva. Após pancreatectomia total, há insuficiência endócrina (necessidade de insulina) e exócrina (reposição de enzimas). <b>Na prova:</b> ambas são operações excepcionais em trauma; a preservação de tecido viável e o controle de danos são prioritários.</p></div></div></details><details class=\"modality-study\" open><summary><b>ILUSTRAÇÃO 5 · PEÇA ANATÔMICA — CABEÇA, PROCESSO UNCINADO E DUCTOS</b><span>Anatomia e interpretação</span></summary><div class=\"modality-inner\"><svg viewBox=\"0 0 650 245\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"650\" height=\"245\" rx=\"12\" fill=\"#f2f8f9\"/><path d=\"M80 41 C38 51 35 198 100 207 L164 207\" fill=\"none\" stroke=\"#d4a18f\" stroke-width=\"45\" stroke-linecap=\"round\"/><path d=\"M104 118 C160 79 212 117 268 102 C334 83 419 109 552 85\" fill=\"none\" stroke=\"#e5bb6d\" stroke-width=\"48\" stroke-linecap=\"round\"/><path d=\"M541 85 L417 95 L282 103 L184 104 L101 123\" fill=\"none\" stroke=\"#3e8194\" stroke-width=\"6\"/><path d=\"M130 66 L130 143\" fill=\"none\" stroke=\"#61a470\" stroke-width=\"7\"/><g font-family=\"sans-serif\" font-size=\"17\" font-weight=\"600\" fill=\"#24495b\"><text x=\"20\" y=\"22\">Duodeno</text><text x=\"153\" y=\"66\">Cabeça</text><text x=\"300\" y=\"66\">Corpo</text><text x=\"518\" y=\"58\">Cauda</text><text x=\"260\" y=\"159\">Ducto principal</text><text x=\"20\" y=\"233\">Ampola de Vater / papila: união ductal em D2</text></g></svg><div class=\"explainer\"><p>Na quinta imagem, a peça anatômica demonstra a proximidade íntima entre o <b>duodeno em C</b> e a <b>cabeça do pâncreas</b>, além de corpo, cauda, <b>processo uncinado</b>, Wirsung, eventual ducto acessório de Santorini, papila menor e papila maior. O processo uncinado estende-se posteriormente aos vasos mesentéricos superiores; reconhecer suas relações é importante em lesões pancreatoduodenais complexas. <b>Na prova:</b> diferenciar ruptura distal de Wirsung de lesão de cabeça/ampola.</p></div></div></details></div><p class=\"source\">Referências anatômicas complementares: <a target=\"_blank\" rel=\"noopener\" href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC5199143/\">Surgical strategy and outcomes in duodenal GIST (ilustração original 2)</a>; <a target=\"_blank\" rel=\"noopener\" href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC6907251/\">WSES-AAST trauma pancreatoduodenal</a>. Figuras acima são esquemas de estudo, não representações técnicas completas de procedimentos.</p><h2 class=\"section-band\">02 · FISIOPATOLOGIA — O QUE ACONTECE COM OS TECIDOS?</h2><div class=\"flowchart\"><div class=\"step\" style=\"width:100%\">Impacto epigástrico → compressão do pâncreas/duodeno contra a coluna vertebral</div><em>↓</em><div class=\"step\" style=\"width:100%\"><b>Pâncreas:</b> contusão, laceração ou ruptura do ducto principal.<br><b>Duodeno:</b> hemorragia intramural ou perfuração transmural</div><em>↓</em><div class=\"step\" style=\"width:100%\"><b>Ruptura ductal:</b> extravasamento de enzimas e secreções, inflamação, coleções e fístula.<br><b>Hematoma duodenal:</b> estreitamento luminal e obstrução, sem necessariamente perfurar.<br><b>Perfuração:</b> bile/conteúdo entérico no retroperitônio → abscesso/sepse</div></div><p><b>Por que amilase e lipase normais não excluem?</b> Nas primeiras horas pode ainda não haver elevação sérica. A TC inicial também pode ser inespecífica. É o conjunto mecanismo, dor persistente, exames seriados e imagem de reavaliação que sustenta a investigação.</p><h2 class=\"section-band\">03 · CLASSIFICAÇÕES AAST — PÂNCREAS E DUODENO</h2><div class=\"table-scroll\"><table><thead><tr><th>AAST</th><th>Pâncreas</th><th>Duodeno</th></tr></thead><tbody><tr><td>I</td><td>Contusão pequena/laceração superficial sem lesão ductal</td><td>Hematoma de 1 segmento ou laceração parcial sem perfuração</td></tr><tr><td>II</td><td>Contusão/laceração maior sem lesão ductal</td><td>Hematoma de mais de 1 segmento ou laceração <50% circunferência</td></tr><tr><td>III</td><td>Transecção distal ou laceração distal com ruptura ductal</td><td>Laceração 50–75% de D2 ou 50–100% de D1, D3, D4</td></tr><tr><td>IV</td><td>Transecção proximal ou lesão parenquimatosa envolvendo ampola/região proximal</td><td>Laceração >75% de D2 ou lesão de ampola/colédoco distal</td></tr><tr><td>V</td><td>Destruição maciça da cabeça</td><td>Destruição maciça do complexo duodenopancreático ou desvascularização duodenal</td></tr></tbody></table></div><p>A classificação descreve anatomia. Conduta deve integrar hemodinâmica, estabilidade, tempo de lesão, ductos e experiência do centro. No pâncreas <b>AAST I–II sem ruptura ductal</b> frequentemente permite manejo não operatório; <b>AAST III distal com ducto lesado</b> frequentemente leva à pancreatectomia distal em adultos. Grau IV/V proximal exige decisões especializadas.</p><h2 class=\"section-band\">04 · IMAGEM: TC, CPRM, CPRE E CASOS RADIOLÓGICOS REAIS</h2><div class=\"note\" style=\"background:#e9f7f3;border-left-color:#16805d\"><b>GALERIA DE EXAMES — VERSÃO REVISADA</b><br>Se a imagem original não abrir, o site tentará uma segunda fonte automaticamente. Para cada exame, há também link de abertura direta e referência do artigo científico. A presença do cartão sem fotografia indica bloqueio de carregamento externo no navegador.</div><p class=\"explainer\">ATLAS DE RADIOLOGIA REAL — interpretação guiada de exames de TC, CPRM e CPRE, com imagens de artigos científicos. Os exemplos distinguem <b>lesão parenquimatosa</b>, <b>ruptura do Wirsung</b>, <b>hematoma duodenal</b> e <b>perfuração retroperitoneal</b>.</p><div class=\"t16-exam-grid\"><figure class=\"realcase-card t16-image-card\"><h4>1. TC · Transecção pancreática traumática</h4><img src=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/28ff/4096521/cc5fe2d8c53c/1752-1947-8-173-1.jpg\" data-backup=\"https://wsrv.nl/?url=https%3A%2F%2Fcdn.ncbi.nlm.nih.gov%2Fpmc%2Fblobs%2F28ff%2F4096521%2Fcc5fe2d8c53c%2F1752-1947-8-173-1.jpg\" loading=\"lazy\" referrerpolicy=\"no-referrer\" alt=\"TC · Transecção pancreática traumática\" onerror=\"if(!this.dataset.triedBackup){this.dataset.triedBackup='1';this.src=this.dataset.backup;return;}this.style.display='none';this.nextElementSibling.style.display='block'\" style=\"max-width:100%;width:100%;height:auto;max-height:320px;object-fit:contain\"><div style=\"display:none;padding:12px;border:1px dashed #d1dedf;border-radius:8px;background:#f7fafb\">Prévia indisponível no navegador. Use o link do artigo original logo abaixo para abrir a figura.</div><div class=\"exam-what\"><b>O que identificar:</b> A <b>seta branca</b> aponta laceração de espessura total no colo do pâncreas. Procure a linha de interrupção parenquimatosa e líquido na loja pancreática. A TC sugere ruptura ductal, mas pode não delinear diretamente o Wirsung.</div><div class=\"exam-source\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4096521/\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir artigo original com as imagens</a> · Casos clínicos reais publicados, distintos dos casos fictícios da ficha.</div><p class=\"t16-direct\"><a href=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/28ff/4096521/cc5fe2d8c53c/1752-1947-8-173-1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir este exame de imagem diretamente em tamanho original</a></p></figure><figure class=\"realcase-card t16-image-card\"><h4>2. CPRM · Ruptura do ducto pancreático principal</h4><img src=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/28ff/4096521/4ba51f40ea31/1752-1947-8-173-2.jpg\" data-backup=\"https://wsrv.nl/?url=https%3A%2F%2Fcdn.ncbi.nlm.nih.gov%2Fpmc%2Fblobs%2F28ff%2F4096521%2F4ba51f40ea31%2F1752-1947-8-173-2.jpg\" loading=\"lazy\" referrerpolicy=\"no-referrer\" alt=\"CPRM · Ruptura do ducto pancreático principal\" onerror=\"if(!this.dataset.triedBackup){this.dataset.triedBackup='1';this.src=this.dataset.backup;return;}this.style.display='none';this.nextElementSibling.style.display='block'\" style=\"max-width:100%;width:100%;height:auto;max-height:320px;object-fit:contain\"><div style=\"display:none;padding:12px;border:1px dashed #d1dedf;border-radius:8px;background:#f7fafb\">Prévia indisponível no navegador. Use o link do artigo original logo abaixo para abrir a figura.</div><div class=\"exam-what\"><b>O que identificar:</b> As <b>setas</b> indicam interrupção do ducto e comunicação com uma coleção (<b>asterisco</b>). A CPRM mostra líquido biliar/pancreático em alto sinal e permite avaliar a continuidade ductal.</div><div class=\"exam-source\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4096521/\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir artigo original com as imagens</a> · Casos clínicos reais publicados, distintos dos casos fictícios da ficha.</div><p class=\"t16-direct\"><a href=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/28ff/4096521/4ba51f40ea31/1752-1947-8-173-2.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir este exame de imagem diretamente em tamanho original</a></p></figure><figure class=\"realcase-card t16-image-card\"><h4>3. CPRE · Transecção ductal e extravasamento de contraste</h4><img src=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/28ff/4096521/c5e062bba00c/1752-1947-8-173-3.jpg\" data-backup=\"https://wsrv.nl/?url=https%3A%2F%2Fcdn.ncbi.nlm.nih.gov%2Fpmc%2Fblobs%2F28ff%2F4096521%2Fc5e062bba00c%2F1752-1947-8-173-3.jpg\" loading=\"lazy\" referrerpolicy=\"no-referrer\" alt=\"CPRE · Transecção ductal e extravasamento de contraste\" onerror=\"if(!this.dataset.triedBackup){this.dataset.triedBackup='1';this.src=this.dataset.backup;return;}this.style.display='none';this.nextElementSibling.style.display='block'\" style=\"max-width:100%;width:100%;height:auto;max-height:320px;object-fit:contain\"><div style=\"display:none;padding:12px;border:1px dashed #d1dedf;border-radius:8px;background:#f7fafb\">Prévia indisponível no navegador. Use o link do artigo original logo abaixo para abrir a figura.</div><div class=\"exam-what\"><b>O que identificar:</b> O contraste opacifica o ducto proximal e extravasa pela ruptura, sem preencher o segmento distal no caso publicado. Diferencie esse achado de um ducto íntegro; a CPRE pode também permitir stent quando tecnicamente possível.</div><div class=\"exam-source\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4096521/\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir artigo original com as imagens</a> · Casos clínicos reais publicados, distintos dos casos fictícios da ficha.</div><p class=\"t16-direct\"><a href=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/28ff/4096521/c5e062bba00c/1752-1947-8-173-3.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir este exame de imagem diretamente em tamanho original</a></p></figure><figure class=\"realcase-card t16-image-card\"><h4>4. TC · Trauma duodenopancreático e suspeita de perfuração</h4><img src=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/a16e/5893489/f035a33fd212/13244_2018_593_Fig21_HTML.jpg\" data-backup=\"https://wsrv.nl/?url=https%3A%2F%2Fcdn.ncbi.nlm.nih.gov%2Fpmc%2Fblobs%2Fa16e%2F5893489%2Ff035a33fd212%2F13244_2018_593_Fig21_HTML.jpg\" loading=\"lazy\" referrerpolicy=\"no-referrer\" alt=\"TC · Trauma duodenopancreático e suspeita de perfuração\" onerror=\"if(!this.dataset.triedBackup){this.dataset.triedBackup='1';this.src=this.dataset.backup;return;}this.style.display='none';this.nextElementSibling.style.display='block'\" style=\"max-width:100%;width:100%;height:auto;max-height:320px;object-fit:contain\"><div style=\"display:none;padding:12px;border:1px dashed #d1dedf;border-radius:8px;background:#f7fafb\">Prévia indisponível no navegador. Use o link do artigo original logo abaixo para abrir a figura.</div><div class=\"exam-what\"><b>O que identificar:</b> <b>Painel A:</b> hematoma pancreatoduodenal, lesão mural de D3, extravasamento vascular e líquido retroperitoneal. <b>Painel B:</b> líquido retroperitoneal próximo ao duodeno e edema de parede. Exames de pacientes diferentes; contraste e achados devem ser interpretados com a clínica.</div><div class=\"exam-source\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC5893489/\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir artigo original com as imagens</a> · Casos clínicos reais publicados, distintos dos casos fictícios da ficha.</div><p class=\"t16-direct\"><a href=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/a16e/5893489/f035a33fd212/13244_2018_593_Fig21_HTML.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir este exame de imagem diretamente em tamanho original</a></p></figure><figure class=\"realcase-card t16-image-card\"><h4>5. TC · Perfuração duodenal com ar retroperitoneal</h4><img src=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/0179/6771178/ee4b254ca230/NJS-25-213-g001.jpg\" data-backup=\"https://wsrv.nl/?url=https%3A%2F%2Fcdn.ncbi.nlm.nih.gov%2Fpmc%2Fblobs%2F0179%2F6771178%2Fee4b254ca230%2FNJS-25-213-g001.jpg\" loading=\"lazy\" referrerpolicy=\"no-referrer\" alt=\"TC · Perfuração duodenal com ar retroperitoneal\" onerror=\"if(!this.dataset.triedBackup){this.dataset.triedBackup='1';this.src=this.dataset.backup;return;}this.style.display='none';this.nextElementSibling.style.display='block'\" style=\"max-width:100%;width:100%;height:auto;max-height:320px;object-fit:contain\"><div style=\"display:none;padding:12px;border:1px dashed #d1dedf;border-radius:8px;background:#f7fafb\">Prévia indisponível no navegador. Use o link do artigo original logo abaixo para abrir a figura.</div><div class=\"exam-what\"><b>O que identificar:</b> <b>Painel A:</b> pequenas bolhas de ar retroperitoneal ao redor de D3. <b>Painel B:</b> extravasamento de contraste oral para o espaço retroperitoneal. São sinais diretos de perfuração que podem surgir mesmo sem grande pneumoperitônio.</div><div class=\"exam-source\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC6771178/\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir artigo original com as imagens</a> · Casos clínicos reais publicados, distintos dos casos fictícios da ficha.</div><p class=\"t16-direct\"><a href=\"https://cdn.ncbi.nlm.nih.gov/pmc/blobs/0179/6771178/ee4b254ca230/NJS-25-213-g001.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir este exame de imagem diretamente em tamanho original</a></p></figure><figure class=\"realcase-card t16-image-card\"><h4>6. TC · Hematoma intramural duodenal (sem perfuração)</h4><img src=\"data:image/jpeg;base64,\" loading=\"lazy\" alt=\"Eurorad 9052 Figura 3: hematoma intramural duodenal e extensão à gordura retroperitoneal\" style=\"width:100%;max-height:340px;object-fit:contain;background:#111\"><div style=\"display:none;padding:12px;border:1px dashed #d1dedf;border-radius:8px;background:#f7fafb\">Imagem de referência incluída na própria ficha, independentemente do site externo.</div><div class=\"exam-what\"><b>Leitura das imagens:</b> as <b>setas</b> identificam o hematoma intramural duodenal; as <b>pontas de seta</b> mostram sua extensão à gordura retroperitoneal. Não se observam <b>gás extraluminal, líquido livre ou extravasamento de contraste</b> indicativos de perfuração duodenal nesse exame. <b>Macete:</b> hematoma intramural pode causar obstrução sem ruptura transmural.</div><div class=\"exam-source\"><b>Fonte:</b> <a href=\"https://www.eurorad.org/case/9052\" target=\"_blank\" rel=\"noopener noreferrer\">Eurorad, Case 9052</a>. <b>DOI:</b> <a href=\"https://doi.org/10.1594/EURORAD/CASE.9052\" target=\"_blank\" rel=\"noopener noreferrer\">10.1594/EURORAD/CASE.9052</a>. <b>ISSN:</b> 1563-4086. Legenda traduzida e adaptada da imagem do caso clínico original. Reprodução e créditos sujeitos aos termos da fonte.</div><p class=\"t16-direct\"><a href=\"https://www.eurorad.org/case/9052\" target=\"_blank\" rel=\"noopener noreferrer\">Ver figura 3 em tamanho original no Eurorad</a></p></figure></div><div class=\"note\">MACETE RADIOLÓGICO: TC mostra a anatomia e sinais indiretos; CPRM detalha a continuidade ductal; CPRE demonstra o extravasamento diretamente e pode permitir tratamento. Ar extraluminal ao redor de D2–D3 indica suspeita de perfuração retroperitoneal; hematoma mural sem perfuração costuma ser tratado inicialmente sem cirurgia em paciente estável.</div><div class=\"table-scroll\"><table><thead><tr><th>Exame</th><th>Papel</th><th>Limitação</th></tr></thead><tbody><tr><td>TC com contraste IV</td><td>Primeira investigação anatômica no estável</td><td>Pode não demonstrar lesão ductal inicial</td></tr><tr><td>Repetir TC após 12–24 h</td><td>Quando suspeita permanece alta e TC inicial é equívoca</td><td>Não atrasar cirurgia em paciente que deteriora</td></tr><tr><td>CPRM/MRCP</td><td>Visualização não invasiva do ducto pancreático e árvore biliar</td><td>Pode ser inconclusiva</td></tr><tr><td>CPRE/ERCP</td><td>Diagnosticar ruptura ductal e possibilitar stent em casos selecionados</td><td>Invasiva; risco de pancreatite e outras complicações</td></tr><tr><td>Amilase/lipase séricas</td><td>Apoio diagnóstico e evolução</td><td>Normais precocemente não descartam trauma</td></tr></tbody></table></div><h2 class=\"section-band\">05 · FLUXOGRAMA DE ATENDIMENTO E ESCOLHA TERAPÊUTICA</h2><div class=\"flowchart\"><div class=\"step\" style=\"width:100%\">Trauma epigástrico com suspeita pancreatoduodenal → xABCDE e avaliação da perfusão</div><em>↓</em><div class=\"step\" style=\"width:100%\"><b>Instável com indicação operatória:</b> ressuscitação hemostática + laparotomia, controle de hemorragia/contaminação e danos.<br><b>Estável:</b> TC com contraste IV</div><em>↓</em><div class=\"step\" style=\"width:100%\"><b>TC negativa/equívoca, mas dor/mecanismo persistem:</b> observar e considerar repetir TC 12–24 h; CPRM/CPRE se dúvida ductal</div><em>↓</em><div class=\"step\" style=\"width:100%\"><b>Pâncreas AAST I–II, ducto íntegro:</b> manejo conservador selecionado.<br><b>AAST III distal ductal:</b> considerar pancreatectomia distal no adulto.<br><b>Lesões proximais:</b> avaliação multidisciplinar, drenagem e reconstrução individualizada</div><em>↓</em><div class=\"step\" style=\"width:100%\"><b>Duodeno sem perfuração/hematoma:</b> descompressão e suporte.<br><b>Perfuração reparável:</b> duodenorrafia primária.<br><b>Destruição ampular ou choque:</b> controle de danos e reconstrução especializada</div></div><div class=\"note\">FAST e enzimas não excluem lesões retroperitoneais. Princípio: investigar ducto e ampola antes de escolher uma reconstrução pancreatoduodenal complexa.</div><h2 class=\"section-band\">06 · TÉCNICAS OPERATÓRIAS DO PÂNCREAS</h2><div class=\"table-scroll\"><table><thead><tr><th>Técnica</th><th>Quando considerar</th><th>O que faz</th></tr></thead><tbody><tr><td>Manejo não operatório</td><td>Contusão/laceração sem ducto lesado em estável</td><td>Vigilância de dor, inflamação, coleções e lesões associadas</td></tr><tr><td>Pancreatectomia distal</td><td>Transecção distal com ruptura ductal em adulto, especialmente completa</td><td>Remove corpo/cauda a jusante da lesão; preservar baço se tecnicamente possível e seguro</td></tr><tr><td>Drenagem cirúrgica</td><td>Lesões menores encontradas em laparotomia ou manejo de secreções/coleções selecionadas</td><td>Controla extravasamento, mas não substitui tratamento de ducto rompido em todos os casos</td></tr><tr><td>CPRE + stent pancreático</td><td>Lesões ductais selecionadas em pacientes estáveis, sem outra indicação imediata de cirurgia</td><td>Descompressão e, quando tecnicamente possível, ponte através do defeito ductal</td></tr><tr><td>Cirurgia de controle de danos</td><td>Fisiologia muito desfavorável ou lesão proximal complexa</td><td>Controle breve de sangue e secreções; fechamento temporário e reconstrução tardia</td></tr><tr><td>Pancreaticoduodenectomia (Whipple)</td><td>Destruição maciça e irreparável da cabeça/duodeno/ampola, caso excepcional</td><td>Ressecção complexa, frequentemente planejada em etapas após estabilização</td></tr></tbody></table></div><p><b>Complicações da pancreatectomia distal:</b> fístula pancreática do coto, coleções/abscesso, hemorragia, diabetes e insuficiência exócrina conforme extensão ressecada. Esplenectomia associada traz necessidade de prevenção de OPSI.</p><h2 class=\"section-band\">07 · TÉCNICAS DO DUODENO E MANOBRA DE KOCHER</h2><div class=\"table-scroll\"><table><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td>Hematoma intramural sem perfuração</td><td>Jejum/descompressão nasogástrica se necessária, hidratação, suporte nutricional e observação</td></tr><tr><td>Perfuração pequena, viável, distante da papila</td><td>Duodenorrafia/reparo primário sem tensão, evitando estreitamento luminal</td></tr><tr><td>Lesão extensa mas reconstruível</td><td>Ressecção segmentar + anastomose/reconstrução adequada ao segmento</td></tr><tr><td>Perfuração com instabilidade grave</td><td>Controle de danos, controle abreviado de vazamento e drenagem/proteção apropriadas</td></tr><tr><td>Destruição de D2 com papila/cabeça pancreática</td><td>Avaliação hepatopancreatobiliar, frequentemente reconstrução em etapas</td></tr><tr><td>Exclusão pilórica</td><td>Procedimento de derivação historicamente utilizado, NÃO obrigatório em toda perfuração</td></tr></tbody></table></div><p><b>Manobra de Kocher:</b> mobiliza o duodeno e a cabeça pancreática por incisão do peritônio lateral, permitindo examinar sua face posterior, região retroperitoneal e lesões ocultas. Pode ser essencial na exploração de trauma duodenopancreático.</p><p><b>Exclusão pilórica:</b> fechamento temporário do piloro e gastrojejunostomia para desviar conteúdo gástrico do duodeno reparado. Evidência não sustenta seu uso rotineiro em toda lesão duodenal.</p><h2 class=\"section-band\">08 · FÍSTULA PANCREÁTICA, PSEUDOCISTO E ABSCESSO</h2><div class=\"table-scroll\"><table><thead><tr><th>Complicação</th><th>Como reconhecer</th><th>Manejo</th></tr></thead><tbody><tr><td>Vazamento bioquímico</td><td>Amilase elevada no líquido, sem repercussão clínica relevante</td><td>Observação, conforme contexto</td></tr><tr><td>Fístula pancreática clinicamente relevante (ISGPS B/C)</td><td>A partir do DPO 3, amilase no dreno >3× limite superior normal sérico institucional + repercussão clínica/mudança de manejo</td><td>Drenagem, nutrição e manejo de complicações; B requer intervenção/prolonga dreno, C envolve reoperação ou falência orgânica</td></tr><tr><td>Coleção pancreática infectada</td><td>Febre, dor, inflamação, coleção acessível</td><td>Antibióticos + drenagem percutânea/endoscópica conforme anatomia; cirurgia se falha ou deterioração</td></tr><tr><td>Pseudocisto pancreático</td><td>Coleção encapsulada após evolução; sintomas por massa, infecção ou persistência</td><td>Observar se assintomático; drenar seletivamente se sintomático/complicado</td></tr><tr><td>Hemorragia tardia/pseudoaneurisma</td><td>Queda Hb, sangue por dreno ou digestivo, foco arterial</td><td>Angio-TC e embolização se adequado ou cirurgia conforme estabilidade</td></tr><tr><td>Lesão ductal desconectada</td><td>Ducto interrompido, coleção/fístula recorrente</td><td>Avaliação especializada: ERCP, drenagem interna/endoscópica ou cirurgia</td></tr></tbody></table></div><p><b>ISGPS 2016:</b> não chame toda amilase elevada de fístula clínica. O antigo grau A virou “vazamento bioquímico”; a <b>fístula de grau B</b> altera o manejo e a <b>grau C</b> envolve reoperação, falência de órgãos ou morte atribuível. Definição pós-operatória, usada como referência para complicações cirúrgicas traumáticas.</p><div class=\"note\">Macete: amilase elevada = origem pancreática provável; fístula clinicamente relevante = amilase elevada + consequência clínica. Coleção infectada precisa controle de foco.</div><h2 class=\"section-band\">09 · REVISÃO COMPARATIVA DE PROVA</h2><div class=\"table-scroll\"><table><thead><tr><th>Situação</th><th>Conduta-chave</th></tr></thead><tbody><tr><td>Guidão no epigástrio + TC sutil + lipase normal</td><td>Não descartar; observação e reimagem se suspeita persistir</td></tr><tr><td>AAST III corpo/cauda com ducto rompido</td><td>Pancreatectomia distal é opção clássica no adulto</td></tr><tr><td>AAST IV/V proximal/cabeça, papila</td><td>Reconstrução especializada e avaliação vascular/ductal</td></tr><tr><td>Hematoma intramural D2 sem ar extraluminal</td><td>Conservador: descompressão, suporte nutricional e observação</td></tr><tr><td>D2 perfurado, pequena lesão viável longe da papila</td><td>Reparo primário sem tensão, quando possível</td></tr><tr><td>Pringle não se aplica aqui</td><td>Pringle é manobra de inflow hepático; trauma pancreatoduodenal demanda controle específico</td></tr><tr><td>Choque + acidose + hipotermia + coagulopatia</td><td>Controle de danos, não reconstrução prolongada</td></tr><tr><td>Coleção infectada pós-pancreatectomia</td><td>Drenagem e antibióticos, avaliando ducto e necessidade de endoscopia/cirurgia</td></tr></tbody></table></div><p class=\"source\">Referências: <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC6907251/\" target=\"_blank\" rel=\"noopener\">WSES-AAST 2019</a> · <a href=\"https://www.east.org/education-resources/practice-management-guidelines/details/pancreatic-injuries\" target=\"_blank\" rel=\"noopener\">EAST pancreatic trauma</a> · <a href=\"https://pubmed.ncbi.nlm.nih.gov/28040257/\" target=\"_blank\" rel=\"noopener\">ISGPS 2016 fistula</a> · <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12841658/\" target=\"_blank\" rel=\"noopener\">Duodenal Trauma review 2026</a> · <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4663380/\" target=\"_blank\" rel=\"noopener\">Pancreatic CT imaging</a>.</p><section class=\"tc-cases\"><h2 class=\"section-band\">10 · CASOS CLÍNICOS INTERATIVOS · 2 CASOS / 6 MOMENTOS / 12 DECISÕES</h2><div class=\"tc-case-index\">Mesmo padrão de interação da Ficha 7: expanda caso e momentos, selecione A–E e corrija as 6 questões de cada caso. A discussão integrada aparece logo após a correção. <span>Rodada histórica já realizada: <b>12/12 acertos (100%)</b>; novas tentativas não alteram o registro.</span></div><details class=\"tc-case\" open><summary><span class=\"tc-number\">CASO 1</span><b>O pâncreas com lesão ductal inicialmente oculta</b><span class=\"tc-small\">Trauma contuso · Ducto de Wirsung · Pancreatectomia distal</span></summary><div class=\"tc-case-body\"><div class=\"tc-quiz\"><details class=\"tc-stage\" open><summary><span class=\"tc-number\">MOMENTO 1</span><b>Momento 1 — O impacto contra o guidão</b></summary><div class=\"tc-stage-body\"><div class=\"tc-scenario\">Homem, 24 anos, após queda de bicicleta com impacto direto do guidão no epigástrio. Chega consciente, PA 124/78 mmHg, FC 94 bpm e Glasgow 15. Queixa-se de dor epigástrica e náuseas. Lipase sérica inicialmente normal. TC com contraste demonstra pequena densificação da gordura peripancreática e discreto líquido junto ao corpo do pâncreas, sem laceração nítida ou lesão de outro órgão.</div><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 1/12 · Qual a interpretação mais apropriada da TC e da lipase inicial?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q1\" value=\"A\"><span><b>A)</b> Lipase normal exclui lesão pancreática.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q1\" value=\"B\"><span><b>B)</b> A ausência de laceração evidente descarta comprometimento do ducto.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q1\" value=\"C\"><span><b>C)</b> O mecanismo e os achados peripancreáticos mantêm suspeita de lesão; valores iniciais normais não a excluem.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q1\" value=\"D\"><span><b>D)</b> Todo trauma pancreático exige pancreatectomia imediata.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q1\" value=\"E\"><span><b>E)</b> A TC inicial obrigatoriamente identifica toda lesão ductal.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 2/12 · Qual a melhor estratégia inicial nesse paciente estável?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q2\" value=\"A\"><span><b>A)</b> Alta com analgesia.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q2\" value=\"B\"><span><b>B)</b> Laparotomia imediata sem outros indícios.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q2\" value=\"C\"><span><b>C)</b> Observação hospitalar com avaliações seriadas e consideração de TC repetida em 12–24 horas, além de investigação ductal conforme suspeita.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q2\" value=\"D\"><span><b>D)</b> CPRE obrigatória em todos os traumas epigástricos.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q2\" value=\"E\"><span><b>E)</b> Iniciar anticoagulação plena.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset></div></details><details class=\"tc-stage\" ><summary><span class=\"tc-number\">MOMENTO 2</span><b>Momento 2 — O ducto aparece na investigação</b></summary><div class=\"tc-stage-body\"><div class=\"tc-scenario\">Dezoito horas depois, a dor persiste e a lipase aumenta. A nova TC mostra transecção do parênquima pancreático no corpo distal, à esquerda dos vasos mesentéricos superiores. A CPRM sugere interrupção do ducto pancreático principal na região correspondente. O paciente continua hemodinamicamente estável.</div><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 3/12 · A nova imagem mostra transecção do corpo/cauda e suspeita de interrupção do ducto principal à esquerda dos vasos mesentéricos. Qual classificação é mais provável?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q3\" value=\"A\"><span><b>A)</b> AAST I.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q3\" value=\"B\"><span><b>B)</b> AAST II.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q3\" value=\"C\"><span><b>C)</b> AAST III.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q3\" value=\"D\"><span><b>D)</b> AAST IV.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q3\" value=\"E\"><span><b>E)</b> AAST V.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset><fieldset class=\"tc-question\" data-answer=\"B\"><legend>Decisão 4/12 · No adulto estável com transecção distal completa e ruptura ductal confirmada, qual intervenção é a opção operatória clássica?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q4\" value=\"A\"><span><b>A)</b> Pancreaticoduodenectomia obrigatória.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q4\" value=\"B\"><span><b>B)</b> Pancreatectomia distal, com preservação esplênica se viável e apropriada.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q4\" value=\"C\"><span><b>C)</b> Apenas sutura da cápsula, sem avaliar ducto.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q4\" value=\"D\"><span><b>D)</b> Colectomia esquerda.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q4\" value=\"E\"><span><b>E)</b> Colecistectomia isolada.</span></label><div class=\"tc-rationale\" hidden>Gabarito: B. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset></div></details><details class=\"tc-stage\" ><summary><span class=\"tc-number\">MOMENTO 3</span><b>Momento 3 — Uma coleção após a operação</b></summary><div class=\"tc-stage-body\"><div class=\"tc-scenario\">Após tratamento cirúrgico da lesão, o paciente evolui inicialmente estável. No sexto dia, apresenta febre e dor epigástrica. A TC demonstra coleção peripancreática de 7 cm, com sinais inflamatórios, acessível por trajeto percutâneo. O líquido obtido apresenta amilase elevada. Hemoculturas foram coletadas, e não há choque ou peritonite difusa.</div><fieldset class=\"tc-question\" data-answer=\"B\"><legend>Decisão 5/12 · Após a cirurgia, há coleção peripancreática crescente com alto teor de amilase no líquido drenado. Qual hipótese é prioritária?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q5\" value=\"A\"><span><b>A)</b> Hemobilia.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q5\" value=\"B\"><span><b>B)</b> Fístula pancreática pós-traumática ou pós-operatória.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q5\" value=\"C\"><span><b>C)</b> Perfuração retal.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q5\" value=\"D\"><span><b>D)</b> Colecistite calculosa obrigatória.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q5\" value=\"E\"><span><b>E)</b> Trombose venosa profunda como causa da coleção.</span></label><div class=\"tc-rationale\" hidden>Gabarito: B. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 6/12 · Qual é a abordagem mais apropriada para uma coleção pancreática infectada, acessível, em paciente estável?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q6\" value=\"A\"><span><b>A)</b> Alta com dieta oral.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q6\" value=\"B\"><span><b>B)</b> Antibiótico isolado sempre resolve, sem avaliar a coleção.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q6\" value=\"C\"><span><b>C)</b> Antibióticos e drenagem adequada da coleção, com avaliação da anatomia ductal e possível tratamento endoscópico se indicado.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q6\" value=\"D\"><span><b>D)</b> Pancreaticoduodenectomia imediata em todos os casos.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q6\" value=\"E\"><span><b>E)</b> Anticoagulação plena.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset></div></details><button class=\"action\" data-tc-check type=\"button\">Corrigir decisões do Caso 1</button><span class=\"tc-result\"></span><div class=\"tc-case-discussion\" hidden style=\"margin-top:14px;background:#f0faf6;border-left:4px solid #168361;padding:15px;border-radius:9px;font-size:14px;line-height:1.7\"><h3>DISCUSSÃO INTEGRADA — CASO 1</h3><b>Discussão clínica integrada · 6/6.</b> O impacto do guidão comprime pâncreas contra coluna, causando contusão ou transecção; lipase inicial e TC podem ser falsamente tranquilizadoras. Em paciente estável com dor persistente, observação e TC repetida em 12–24 h são apropriadas. Transecção distal à esquerda dos vasos mesentéricos com lesão do Wirsung = <b>AAST III</b>; em adulto, pancreatectomia distal é abordagem operatória clássica, preservando baço quando viável. Após a operação, febre e coleção crescente rica em amilase apontam para vazamento/fístula pancreática com infecção. Tratar com antibióticos quando infectado e drenagem adequada; avaliar anatomia ductal e possibilidade de intervenção endoscópica. <b>Muda conduta:</b> lesão proximal/ampular requer reconstrução especializada; peritonite/choque ou controle de foco falho favorecem abordagem urgente. <b>ISGPS:</b> amilase alta isolada não define fístula clinicamente relevante.</div></div></div></details><details class=\"tc-case\" ><summary><span class=\"tc-number\">CASO 2</span><b>O duodeno que parecia apenas obstruído</b><span class=\"tc-small\">Hematoma intramural · Perfuração de D2 · Controle de danos</span></summary><div class=\"tc-case-body\"><div class=\"tc-quiz\"><details class=\"tc-stage\" open><summary><span class=\"tc-number\">MOMENTO 1</span><b>Momento 1 — Vômitos após impacto abdominal</b></summary><div class=\"tc-stage-body\"><div class=\"tc-scenario\">Mulher, 32 anos, após colisão automobilística com impacto da região epigástrica contra o volante. PA 118/76 mmHg, FC 92 bpm, sem defesa ou descompressão brusca. Apresenta vômitos progressivos. TC contrastada demonstra hematoma intramural volumoso em D2 com estreitamento luminal, sem sinais de perfuração ou lesão vascular importante.</div><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 7/12 · Uma TC em paciente estável revela grande hematoma intramural de D2 com redução importante da luz, mas sem ar extraluminal ou extravasamento. Qual é a conduta inicial?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q7\" value=\"A\"><span><b>A)</b> Duodenopancreatectomia imediata.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q7\" value=\"B\"><span><b>B)</b> Reparo duodenal primário mesmo sem perfuração.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q7\" value=\"C\"><span><b>C)</b> Tratamento não operatório com jejum, descompressão conforme necessidade, suporte nutricional e vigilância.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q7\" value=\"D\"><span><b>D)</b> Colostomia de derivação obrigatória.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q7\" value=\"E\"><span><b>E)</b> Alta imediata, pois hematoma intramural nunca obstrui.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset><fieldset class=\"tc-question\" data-answer=\"A\"><legend>Decisão 8/12 · Por que esse hematoma pode causar vômitos persistentes mesmo sem perfuração?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q8\" value=\"A\"><span><b>A)</b> O hematoma intramural ocupa espaço na parede e estreita a luz duodenal, dificultando o esvaziamento gástrico.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q8\" value=\"B\"><span><b>B)</b> O hematoma obrigatoriamente bloqueia o colédoco.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q8\" value=\"C\"><span><b>C)</b> Há sempre transecção pancreática.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q8\" value=\"D\"><span><b>D)</b> A ausência de peritonite indica íleo paralítico sem obstrução.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q8\" value=\"E\"><span><b>E)</b> O sangue intramural é eliminado diretamente pela papila.</span></label><div class=\"tc-rationale\" hidden>Gabarito: A. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset></div></details><details class=\"tc-stage\" ><summary><span class=\"tc-number\">MOMENTO 2</span><b>Momento 2 — Uma nova imagem muda o diagnóstico</b></summary><div class=\"tc-stage-body\"><div class=\"tc-scenario\">Durante a internação, apesar do suporte, apresenta piora da dor, febre, leucocitose e taquicardia. A TC de reavaliação demonstra focos de gás retroperitoneal adjacentes a D2, líquido periduodenal e descontinuidade focal da parede. Na exploração, observa-se uma perfuração pequena com bordas viáveis, sem comprometimento aparente da ampola ou colédoco distal.</div><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 9/12 · Após deterioração, surgem ar retroperitoneal, líquido periduodenal e descontinuidade mural de D2. Qual a prioridade?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q9\" value=\"A\"><span><b>A)</b> Observar, pois o duodeno é retroperitoneal.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q9\" value=\"B\"><span><b>B)</b> CPRE como único tratamento obrigatório para qualquer perfuração.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q9\" value=\"C\"><span><b>C)</b> Exploração cirúrgica urgente para controlar perfuração e contaminação.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q9\" value=\"D\"><span><b>D)</b> Anticoagulação plena.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q9\" value=\"E\"><span><b>E)</b> Alta se o paciente ainda estiver sem pneumoperitônio livre abundante.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset><fieldset class=\"tc-question\" data-answer=\"B\"><legend>Decisão 10/12 · Na operação, a perfuração de D2 é relativamente pequena, distante da ampola, bordas viáveis e reparável sem tensão. Qual técnica deve ser considerada preferencialmente?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q10\" value=\"A\"><span><b>A)</b> Duodenopancreatectomia por rotina.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q10\" value=\"B\"><span><b>B)</b> Reparo primário da lesão duodenal, com medidas complementares conforme necessidade.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q10\" value=\"C\"><span><b>C)</b> Exclusão pilórica obrigatória em toda lesão de D2.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q10\" value=\"D\"><span><b>D)</b> Ressecção total do duodeno.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q10\" value=\"E\"><span><b>E)</b> Apenas packing, sem controle da saída de conteúdo duodenal, mesmo estável.</span></label><div class=\"tc-rationale\" hidden>Gabarito: B. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset></div></details><details class=\"tc-stage\" ><summary><span class=\"tc-number\">MOMENTO 3</span><b>Momento 3 — A fisiologia muda durante a cirurgia</b></summary><div class=\"tc-stage-body\"><div class=\"tc-scenario\">Durante a intervenção, a paciente apresenta sangramento importante de lesão associada, evoluindo com hipotermia de 34 °C, pH 7,12, coagulopatia e necessidade crescente de transfusão. Considere também um segundo cenário: a lesão duodenal seria extensa, destrutiva, atingindo a região ampular e a cabeça pancreática.</div><fieldset class=\"tc-question\" data-answer=\"B\"><legend>Decisão 11/12 · Durante o reparo, o paciente evolui com pH 7,12, temperatura 34 °C, coagulopatia e necessidade crescente de hemocomponentes. O que muda?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q11\" value=\"A\"><span><b>A)</b> É obrigatório completar reconstrução complexa de longa duração.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q11\" value=\"B\"><span><b>B)</b> Priorizar cirurgia de controle de danos, hemostasia, controle abreviado da contaminação e reconstrução diferida quando necessário.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q11\" value=\"C\"><span><b>C)</b> Realizar pancreatectomia total profilática.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q11\" value=\"D\"><span><b>D)</b> Fechar definitivamente o abdome sob tensão.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q11\" value=\"E\"><span><b>E)</b> Interromper ressuscitação para realizar exame de imagem.</span></label><div class=\"tc-rationale\" hidden>Gabarito: B. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset><fieldset class=\"tc-question\" data-answer=\"C\"><legend>Decisão 12/12 · Em uma lesão destrutiva de D2 associada à cabeça pancreática e à região ampular, qual é o princípio cirúrgico mais adequado?</legend><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q12\" value=\"A\"><span><b>A)</b> Toda lesão de D2 é tratada com sutura simples, independentemente da papila.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q12\" value=\"B\"><span><b>B)</b> Toda lesão pancreatoduodenal exige Whipple imediato.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q12\" value=\"C\"><span><b>C)</b> Avaliar ductos, papila, viabilidade e estruturas vasculares; controlar danos e planejar reconstrução especializada, reservando pancreaticoduodenectomia para situações excepcionais.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q12\" value=\"D\"><span><b>D)</b> Colostomia em alça é o único tratamento necessário.</span></label><label class=\"tc-choice\"><input type=\"radio\" name=\"t16q12\" value=\"E\"><span><b>E)</b> Ignorar a via biliar, pois ela não influencia a reconstrução.</span></label><div class=\"tc-rationale\" hidden>Gabarito: C. A justificativa e as mudanças de conduta estão integradas na discussão clínica abaixo do caso.</div></fieldset></div></details><button class=\"action\" data-tc-check type=\"button\">Corrigir decisões do Caso 2</button><span class=\"tc-result\"></span><div class=\"tc-case-discussion\" hidden style=\"margin-top:14px;background:#f0faf6;border-left:4px solid #168361;padding:15px;border-radius:9px;font-size:14px;line-height:1.7\"><h3>DISCUSSÃO INTEGRADA — CASO 2</h3><b>Discussão clínica integrada · 6/6.</b> Hematoma intramural em D2 estreita a luz e causa vômitos, mas sem perfuração pode ser tratado inicialmente de forma conservadora, com descompressão e suporte. Nova piora com gás retroperitoneal, líquido e descontinuidade mural indica perfuração e exploração. Se pequena, viável, longe da ampola e sem tensão, <b>duodenorrafia primária</b> é preferível; exclusão pilórica não é obrigatória. Se a fisiologia deteriora com pH 7,12, T 34 °C e coagulopatia, fazer <b>controle de danos</b>. D2 destrutivo com cabeça pancreática/ampola requer avaliar ductos, papila e vasos; Whipple é reservado a lesões excepcionais, frequentemente com reconstrução em etapas por equipe experiente. <b>MACETE:</b> hematoma obstrui, perfuração contamina; ducto e papila decidem complexidade.</div></div></div></details></section>";
document.addEventListener('click',function(e){const btn=e.target.closest('[data-tc-check]');if(!btn)return;const quiz=btn.closest('.tc-quiz');if(!quiz)return;const qs=[...quiz.querySelectorAll('.tc-question')];if(qs.length!==6||qs.some(q=>!q.querySelector('input:checked')))return;const d=quiz.querySelector('.tc-case-discussion');if(d)d.hidden=false;});
